import contextlib
import io
import unittest

from textkit import near
from textkit.cli import main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class LevenshteinTest(unittest.TestCase):
    def test_known_distances(self):
        self.assertEqual(near.levenshtein("kitten", "sitting"), 3)
        self.assertEqual(near.levenshtein("helo", "hello"), 1)
        self.assertEqual(near.levenshtein("", "abc"), 3)
        self.assertEqual(near.levenshtein("abc", ""), 3)
        self.assertEqual(near.levenshtein("same", "same"), 0)

    def test_is_symmetric(self):
        self.assertEqual(near.levenshtein("flaw", "lawn"), near.levenshtein("lawn", "flaw"))


class ClosestTest(unittest.TestCase):
    def test_picks_nearest(self):
        self.assertEqual(near.closest("helo", ["hello", "world", "help"]), "hello")

    def test_ties_go_to_first(self):
        self.assertEqual(near.closest("cat", ["cot", "cab"]), "cot")
        self.assertEqual(near.closest("cat", ["cab", "cot"]), "cab")

    def test_none_when_beyond_max_distance(self):
        self.assertIsNone(near.closest("zzzz", ["hello"]))

    def test_max_distance_is_inclusive(self):
        self.assertEqual(near.closest("abc", ["abd"], max_distance=1), "abd")
        self.assertIsNone(near.closest("abc", ["abd"], max_distance=0))

    def test_empty_candidates(self):
        self.assertIsNone(near.closest("word", []))

    def test_negative_max_distance_raises(self):
        with self.assertRaises(ValueError):
            near.closest("word", ["word"], max_distance=-1)

    def test_negative_max_distance_raises_even_without_candidates(self):
        with self.assertRaises(ValueError):
            near.closest("word", [], max_distance=-1)


class NearCliTest(unittest.TestCase):
    def test_prints_match(self):
        self.assertEqual(run("near", "helo", "hello", "help"), (0, "hello\n", ""))

    def test_default_max_is_two(self):
        self.assertEqual(run("near", "helo", "xxxxhello"), (1, "", "no match\n"))
        self.assertEqual(run("near", "helo", "heo"), (0, "heo\n", ""))

    def test_max_option(self):
        self.assertEqual(run("near", "zzzz", "hello", "--max", "10"), (0, "hello\n", ""))
        self.assertEqual(run("near", "zzzz", "hello", "--max", "0"), (1, "", "no match\n"))

    def test_no_match_exits_1(self):
        self.assertEqual(run("near", "zzzz", "hello"), (1, "", "no match\n"))

    def test_negative_max_is_error_exit_2(self):
        code, out, err = run("near", "helo", "hello", "--max", "-1")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_json_wraps_output(self):
        code, out, _ = run("--json", "near", "helo", "hello")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["hello"]', out)

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("near", out.split())


if __name__ == "__main__":
    unittest.main()

